      "mental_workplace": "🧠 Mental + workplace",
      "mid_career_typical": "mid-career typical",
      "mig_fcaw_wires": "🪢 MIG + FCAW wires",
      "mig_gmaw": "MIG / GMAW",
      "mig_gmaw_2": "MIG / GMAW",
